function bDescribe(){const q=QUOTES[selectedService];if(!q)return '';const ok=describeText.trim().length>0;return `<h1 style="${S.h1}">${q.title}</h1><p style="${S.sub}">${q.sub}</p><textarea id="dom-describe" rows="6" style="width:100%!important;padding:14px!important;background:#F7FAFC!important;border:1.5px solid ${ok?BLUE:LINE}!important;color:${INK}!important;border-radius:10px!important;font-size:16px!important;box-sizing:border-box!important;resize:vertical!important;font-family:inherit!important;line-height:1.6!important;margin-bottom:6px!important;" placeholder="${q.placeholder}">${describeText.replace(/</g,'&lt;')}</textarea><p style="font-size:13px!important;color:${MUTE}!important;margin:0 0 4px 0!important;">No payment now — we'll review and follow up with next steps.</p><div style="${S.actions}"><button id="btn-prev" style="${S.btnSec}">← Back</button><button id="btn-next" style="${ok?S.btnPri:S.btnDis}" ${!ok?'disabled':''}>Continue →</button></div>`;}
